-- The campaign book's rules text, for signed-in players.
--
-- Rewritten at v0.37.0, before this migration had been applied to remote, so
-- the append-only rule had not yet attached to it. It used to describe a gate
-- (an ownership question and per-arsenal entitlement, migrations 0008 and
-- 0009). The owner retired that gate and both migrations were deleted unapplied.
--
--   * There is NO public read. `/api/book` requires a session.
--   * There is NO write endpoint. Rows are loaded by hand with
--     `wrangler d1 execute --file`, from SQL generated by
--     `scripts/book-to-sql.mjs`. A table with no write surface cannot be
--     tampered with through the app.
--   * Switching it off is `DELETE FROM book_text`. That is why the text is here
--     and not in the public repository, whose history keeps everything.
--
-- The keys match `src/lib/book.js` exactly. Deliberately no `owner_user_id`:
-- this is shared reference data, not anybody's campaign.

CREATE TABLE IF NOT EXISTS book_text (
  key        TEXT PRIMARY KEY,
  text       TEXT NOT NULL,
  updated_at INTEGER NOT NULL
);
